import{_ as t,o as a,c as r,ah as o}from"./chunks/framework.DDXs_i7t.js";const m=JSON.parse(`{"title":"March 03: Daily Recap – The Wöginger Trial at Linz Regional Court","description":"A summary of the first day of August Wöginger's trial in Linz. Patronage vs. Criminal Law.","frontmatter":{"title":"March 03: Daily Recap – The Wöginger Trial at Linz Regional Court","description":"A summary of the first day of August Wöginger's trial in Linz. Patronage vs. Criminal Law.","date":"2026-03-03T00:00:00.000Z"},"headers":[],"relativePath":"en/logbuch/2026-03-03-zusammenfassung-woeginger-prozess.md","filePath":"en/logbuch/2026-03-03-zusammenfassung-woeginger-prozess.md"}`),i={name:"en/logbuch/2026-03-03-zusammenfassung-woeginger-prozess.md"};function n(s,e,h,l,c,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="⚖️-march-03-daily-recap-–-the-woginger-trial-in-linz" tabindex="-1">⚖️ March 03: Daily Recap – The Wöginger Trial in Linz <a class="header-anchor" href="#⚖️-march-03-daily-recap-–-the-woginger-trial-in-linz" aria-label="Permalink to &quot;⚖️ March 03: Daily Recap – The Wöginger Trial in Linz&quot;">​</a></h1><p>Today was the first major showdown at the Linz Regional Court. At the center: <strong>August Wöginger</strong> (ÖVP Club Chairman) and the question of whether an intervention for a party friend (the &quot;62-point candidate&quot;) crossed the line into criminal patronage.</p><h3 id="the-main-conflict" tabindex="-1"><strong>The Main Conflict:</strong> <a class="header-anchor" href="#the-main-conflict" aria-label="Permalink to &quot;**The Main Conflict:**&quot;">​</a></h3><ul><li><strong>Prosecution (WKStA):</strong> Accuses Wöginger of misuse of authority. It is about a &quot;systematic intervention&quot; to ensure that a candidate with lower points (Michael L., 62 points) got the post, while the highly qualified Dr. Christa Scharf (98 points) was passed over.</li><li><strong>Defense (Wöginger):</strong> Argues that it was a &quot;perfectly normal citizen concern&quot; and that he only &quot;forwarded&quot; information.</li></ul><h3 id="the-atmosphere-in-courtroom-114" tabindex="-1"><strong>The Atmosphere in Courtroom 114:</strong> <a class="header-anchor" href="#the-atmosphere-in-courtroom-114" aria-label="Permalink to &quot;**The Atmosphere in Courtroom 114:**&quot;">​</a></h3><p>Linz witnessed a parade of power. Wöginger, always the man of the people, tried to present himself as the victim of a &quot;criminalization of regional politics.&quot; But the dry facts of the qualification matrix (98 vs. 62) stood like a wall in the room.</p><h3 id="relevance-for-the-horten-mystery" tabindex="-1"><strong>Relevance for the &quot;Horten Mystery&quot;:</strong> <a class="header-anchor" href="#relevance-for-the-horten-mystery" aria-label="Permalink to &quot;**Relevance for the &quot;Horten Mystery&quot;:**&quot;">​</a></h3><p>We see here the direct extension of the <strong>Pointillism of Money</strong> into the present. The same mechanisms that allowed Helmut Horten to build his empire are still active today in the form of &quot;favors&quot; and &quot;intervention.&quot;</p><p><strong>Next steps in court:</strong></p><ul><li>Thursday (March 05): The crucial testimony of Dr. Christa Scharf.</li><li>Friday (March 06): Testimony of the beneficiary mayor Michael L.</li></ul><hr><p>👉 <a href="/en/recherche/gericht-woeginger-scharf.html">To the detailed Research File: Wöginger &amp; Scharf</a> 👉 <a href="/en/logbuch/szene-mazenatentum.html">Explore Part 4: The Political Love Story</a></p>',12)])])}const f=t(i,[["render",n]]);export{m as __pageData,f as default};
